100122,"language":"nl","bound_author_id":978300064,"text":"Tijdens een vakantie vindt Timon een boodschap in een fles. Zijn nieuwsgierigheid naar de afzender brengt hem op een ongewoon cruiseschip. Wat als een zoektocht begint, wordt een avontuur waarin de reis niet meer volgens de verwachtingen van een gewone vakantieganger verloopt. Het verhaal gebruikt een fictieve Timon Verbeeck als hoofdpersoon, die tussen nieuwe ontmoetingen en eigenaardige gebeurtenissen probeert te ontdekken waar hij in terechtgekomen is.","source_type":"official_catalog","source_name":"Bibliografische bron; oorspronkelijke gecontroleerde samenvatting","source_url":"https://metadata.isbn.nl/2128607/het-c-r-u-i-s-e-complot.html","provenance":"original_source_reviewed_summary","review_status":"approved","reviewed_at":"2026-11-01T21:37:32Z","review_batch":"nl007-reviewed-batch-09-20261101","evidence":[{"url":"https://metadata.isbn.nl/2128607/het-c-r-u-i-s-e-complot.html","sha256":"843ab5870c80dddf51840cf09425acf03875186b1e5035fe54d2aea1600ba118","checkedAt":"2026-11-01T20:43:47.584Z","fact":"Hardback ISBN 9789464106121 verschijningsdatum 24/09/2026 NUR 283 Fictie 10-12 jaar 282 Fictie 7-9 jaar imprint Horizon uitgever Overamstel Uitgevers taal Nederlands","sourceAuthors":"Timon Verbeeck"},{"url":"https://metadata.isbn.nl/2128607/het-c-r-u-i-s-e-complot.html","checkedAt":"2026-11-01T21:37:32Z","fact":"Work-bound content reviewed; original factual Dutch summary, not source quotation or title-derived content."}]}},{"relation":"works","ref":"work:new-indepuree","key":{"id":978100123},"before":null,"after":{"id":978100123,"title":"In de puree","cover_id":null,"author_id":978300065,"work_type":null,"source_type":"lumiscore_native","open_library_id":null,"first_publish_year":null,"native_identity_key":"nl-reviewed-isbn:9789083624440"}},{"relation":"editions","ref":"edition:9789083624440","key":{"id":978200181},"before":null,"after":{"id":978200181,"title":"In de puree","isbn_10":null,"isbn_13":"9789083624440","work_id":978100123,"cover_id":null,"language":"nld","publisher":"Höngry","publish_date":null,"open_library_edition_id":null}},{"relation":"catalog_edition_metadata","ref":"metadata:9789083624440","key":{"edition_id":"@edition:9789083624440"},"before":null,"after":{"edition_id":"@edition:9789083624440","work_id":978100123,"bound_author_id":978300065,"bound_title":"In de puree","bound_language":"nld","bound_isbn13":"9789083624440","format":"hardcover","cover_url":"https://metadata.isbn.nl/ie_fcache/0000797256_In_de_puree_2_710_130_0_0.jpg","card_cover_url":null,"evidence_url":"https://metadata.isbn.nl/2127134/in-de-puree.html","review_status":"approved","reviewed_at":"2026-11-01T21:37:32Z","review_batch":"nl007-reviewed-batch-09-20261101","evidence":[{"url":"https://metadata.isbn.nl/2127134/in-de-puree.html","sha256":"3b6fb7038484ac28a224069dd6c71fdfbdd42b2125f2ec3a0edd84b76c328d27","checkedAt":"2026-11-01T20:43:49.728Z","fact":"Hardback ISBN 9789083624440 verschijningsdatum 29/09/2026 NUR 273 Prentenboeken ( imprint Höngry uitgever Hongry taal Nederlands","sourceAuthors":"Bieke Biesbrouck"},{"url":"https://metadata.isbn.nl/ie_fcache/0000797256_In_de_puree_2_710_130_0_0.jpg","sha256":"5e4f2eceacf5166e21a854af7fdd427e693c878a3b4d0fa2071e73b4e05c8b42","bytes":98093,"checkedAt":"2026-11-01T21:24:19.187Z","fact":"Exact edition block and human visual review; same observed provider image stem for medium variant."}]}},{"relation":"catalog_work_descriptions","ref":"description:new-indepuree","key":{"work_id":978100123,"language":"nl"},"before":null,"after":{"work_id":978100123,"language":"nl","bound_author_id":978300065,"text":"Teddy Tomaat gaat met zijn vrienden op ontdekking langs een blotevoetenpad. Onderweg wordt er gelopen, gesprongen en geklauterd. Zijn vrienden vragen hem telkens om hulp, en Teddy wil hen graag bijstaan. Maar voortdurend voor anderen klaarstaan maakt het lastig om ook zijn eigen grenzen te voelen. Het prentenboek volgt hoe een gezamenlijk avontuur de vraag oproept wanneer helpen prettig is en wanneer je ook nee mag zeggen.","source_type":"official_catalog","source_name":"Bibliografische bron; oorspronkelijke gecontroleerde samenvatting","source_url":"https://metadata.isbn.nl/2127134/in-de-puree.html","provenance":"original_source_reviewed_summary","review_status":"approved","reviewed_at":"2026-11-01T21:37:32Z","review_batch":"nl007-reviewed-batch-09-20261101","evidence":[{"url":"https://metadata.isbn.nl/2127134/in-de-puree.html","sha256":"3b6fb7038484ac28a224069dd6c71fdfbdd42b2125f2ec3a0edd84b76c328d27","checkedAt":"2026-11-01T20:43:49.728Z","fact":"Hardback ISBN 9789083624440 verschijningsdatum 29/09/2026 NUR 273 Prentenboeken ( imprint Höngry uitgever Hongry taal Nederlands","sourceAuthors":"Bieke Biesbrouck"},{"url":"https://metadata.isbn.nl/2127134/in-de-puree.html","checkedAt":"2026-11-01T21:37:32Z","fact":"Work-bound content reviewed; original factual Dutch summary, not source quotation or title-derived content."}]}}],"bindings":[],"authorCorpora":[]}'::jsonb;a jsonb;b jsonb;actual jsonb;oldrow jsonb;nextrow jsonb;k jsonb;kv record;ids jsonb:='{}';cols text;vals text;v_id bigint;i integer:=0;n integer;begin
 for b in select value from jsonb_array_elements(payload->'bindings') loop
  select to_jsonb(w) into actual from public.works w where id=(b->'work'->>'id')::bigint;
  if actual is distinct from b->'work' and not exists(select 1 from jsonb_array_elements(payload->'actions') p where p->>'relation'='works' and p->'key'=jsonb_build_object('id',(b->'work'->>'id')::bigint) and actual=p->'after') then raise exception 'Work preflight drift';end if;
  select to_jsonb(t) into actual from public.authors t where id=(b->'author'->>'id')::bigint;
  if actual is distinct from b->'author' then raise exception 'Author preflight drift';end if;
 end loop;
 for b in select value from jsonb_array_elements(payload->'authorCorpora') loop
  select coalesce(jsonb_agg(to_jsonb(w) order by id),'[]') into actual from public.works w where author_id=(b->>'author_id')::bigint and not exists(select 1 from jsonb_array_elements(payload->'actions') p where p->>'relation'='works' and p->'before'='null' and w.native_identity_key=p->'after'->>'native_identity_key');
  select coalesce(jsonb_agg(to_jsonb(jsonb_populate_record(null::public.works,value)) order by (value->>'id')::bigint),'[]') into oldrow from jsonb_array_elements(b->'rows');
  select coalesce(jsonb_agg(to_jsonb(jsonb_populate_record(null::public.works,coalesce((select p->'after' from jsonb_array_elements(payload->'actions') p where p->>'relation'='works' and p->'before'<>'null' and p->'key'=jsonb_build_object('id',(v.value->>'id')::bigint)),v.value))) order by (v.value->>'id')::bigint),'[]') into nextrow from jsonb_array_elements(b->'rows') v;
  if actual is distinct from oldrow and actual is distinct from nextrow then raise exception 'New Work author corpus drift; repeat identity review';end if;
 end loop;
 for a in select value from jsonb_array_elements(payload->'actions') loop
  i:=i+1;k:=a->'key';nextrow:=a->'after';oldrow:=a->'before';
  if a->>'relation' not in ('authors','works','editions','catalog_work_descriptions','catalog_edition_metadata') then raise exception 'Unreviewed relation';end if;
  for kv in select * from jsonb_each(nextrow) loop
   if jsonb_typeof(kv.value)='string' and left(kv.value#>>'{}',1)='@' then
    if not ids ? substring(kv.value#>>'{}',2) then raise exception 'Unresolved parent reference';end if;
    nextrow:=jsonb_set(nextrow,array[kv.key],ids->substring(kv.value#>>'{}',2));
   end if;
  end loop;
  for kv in select * from jsonb_each(k) loop
   if jsonb_typeof(kv.value)='string' and left(kv.value#>>'{}',1)='@' then k:=jsonb_set(k,array[kv.key],ids->substring(kv.value#>>'{}',2));end if;
  end loop;
  execute format('select to_jsonb(t) from public.%I t where to_jsonb(t) @> $1 for update',a->>'relation') into actual using k;
  if oldrow<>'null'::jsonb then
   execute format('select to_jsonb(jsonb_populate_record(null::public.%I,$1))',a->>'relation') into oldrow using oldrow;
   execute format('select to_jsonb(jsonb_populate_record(null::public.%I,$1))',a->>'relation') into nextrow using nextrow;
   if actual is not distinct from nextrow then continue;end if;
   if actual is distinct from oldrow then raise exception 'Changed existing row in % at action %',a->>'relation',i;end if;
   select string_agg(format('%I=(jsonb_populate_record(null::public.%I,$1)).%I',key,a->>'relation',key),',') into cols from jsonb_each(nextrow) where value is distinct from oldrow->key;
   execute format('update public.%I t set %s where to_jsonb(t) @> $2 returning to_jsonb(t)',a->>'relation',cols) into actual using nextrow,k;
   insert into catalog_release_receipt values(i,a->>'relation',k,oldrow,actual);
  elsif actual is not null then
   if a->>'relation' in ('catalog_work_descriptions','catalog_edition_metadata') then
    execute format('select to_jsonb(jsonb_populate_record(null::public.%I,$1))',a->>'relation') into nextrow using nextrow;
    if actual is distinct from nextrow then raise exception 'Existing reviewed presentation differs; never overwrite';end if;
   elsif not actual @> nextrow then raise exception 'Existing natural identity differs';end if;
  else
   if a->>'relation'='editions' and exists(select 1 from public.editions e where (nextrow->>'isbn_13' is not null and regexp_replace(coalesce(e.isbn_13,''),'[-[:space:]]','','g')=nextrow->>'isbn_13') or (nextrow->>'isbn_10' is not null and upper(regexp_replace(coalesce(e.isbn_10,''),'[-[:space:]]','','g'))=nextrow->>'isbn_10') or (nextrow->>'open_library_edition_id' is not null and e.open_library_edition_id=nextrow->>'open_library_edition_id')) then raise exception 'Global edition identity collision';end if;
   select string_agg(format('%I',key),',' order by key),string_agg(format('(jsonb_populate_record(null::public.%I,$1)).%I',a->>'relation',key),',' order by key) into cols,vals from jsonb_each(nextrow);
   execute format('insert into public.%I(%s) select %s returning to_jsonb(%I)',a->>'relation',cols,vals,a->>'relation') into actual using nextrow;
   insert into catalog_release_receipt values(i,a->>'relation',k,null,actual);
  end if;
  if actual ? 'id' then ids:=jsonb_set(ids,array[a->>'ref'],actual->'id');end if;
 end loop;
 select count(*) into n from catalog_release_receipt;
 if n not in (0,28) then raise exception 'Partial install/replay; expected zero or all actions, got %',n;end if;
end;$release$;
select jsonb_build_object('project','hlvujbrmfdlrfxdjwsmb','batch','nl007-reviewed-batch-09-20261101-test','rows',coalesce(jsonb_agg(to_jsonb(r) order by seq),'[]')) as receipt from catalog_release_receipt r;
